/**
 * RGBA color (r, g, b, a). Mirrors CSS rgba() channel layout used across runtimes.
 * Node has no built-in Color type; this minimal class is used as a Map key for outbound marshaling.
 */
/**
 * Normalize an ARGB channel to unsigned int 0-255 for wire encoding.
 * @param {number} value
 * @returns {number}
 */
export function colorChannel(value: number): number;
/**
 * 2D point aligned with {@link https://developer.mozilla.org/en-US/docs/Web/API/DOMPoint DOMPoint} (x, y).
 * Node has no built-in Point type; this minimal class is used as a Map key for outbound marshaling.
 */
export class Point {
    /**
     * @param {number} x
     * @param {number} y
     */
    constructor(x: number, y: number);
    x: number;
    y: number;
}
export class Color {
    /**
     * @param {number} r
     * @param {number} g
     * @param {number} b
     * @param {number} [a=255]
     */
    constructor(r: number, g: number, b: number, a?: number);
    r: number;
    g: number;
    b: number;
    a: number;
}
/**
 * Duration in milliseconds. Node has no built-in duration type; inbound parsers
 * normalize remote durations to a number, and this wrapper enables outbound marshaling.
 */
export class Duration {
    /**
     * @param {number} milliseconds
     */
    constructor(milliseconds: number);
    milliseconds: number;
}
/**
 * UUID string wrapper. Node has no built-in UUID type; enables outbound marshaling.
 */
export class Uuid {
    /**
     * @param {string} value
     */
    constructor(value: string);
    value: string;
    toString(): string;
}
/**
 * Clock time without date (maps to Ruby Hypertube::Utils::TimeOfDay).
 */
export class TimeOfDay {
    /**
     * @param {number} hour
     * @param {number} min
     * @param {number} sec
     * @param {number} [nsec=0]
     */
    constructor(hour: number, min: number, sec: number, nsec?: number);
    hour: number;
    min: number;
    sec: number;
    nsec: number;
}
